def baseline_bounds(model: Model, manifest: dict[str, Any], cfg: dict[str, Any],
                    external: set[str] | None = None) -> tuple[np.ndarray, np.ndarray]:
    """Closed-by-default medium: every external exchange not in the medium has uptake closed,
    and every undeclared single-metabolite reaction (sink / demand / biomass drain) has its
    uptake direction closed so it cannot supply metabolites from nothing."""
    external = validate_boundary(model, manifest) if external is None else external
    lb, ub = model.lb.copy(), model.ub.copy()
    medium = manifest.get("baseline", {}).get("medium", {})
    for rid in model.rxn_ids:
        if model.is_single_metabolite(rid) and rid not in medium:
            close_uptake(model, lb, ub, rid)
    for rid, rate in medium.items():
        col, coeff = model.exchange(rid)
        if coeff > 0:
            ub[col] = float(rate)
        else:
            lb[col] = -float(rate)
    m = manifest["objectives"]["maintenance"]
    if m != "none":
        if m["reaction"] not in model.rxn_index:
            raise ManifestError(f"maintenance reaction not in model: {m['reaction']}")
        col = model.rxn_index[m["reaction"]]
        lb[col] = max(lb[col], float(m["lower_bound"]))
    return lb, ub


def apply_mods(model: Model, manifest: dict[str, Any], cfg: dict[str, Any],
               lb: np.ndarray, ub: np.ndarray, mods: list[dict[str, Any]],
               external: set[str] | None = None) -> list[str]:
    """Apply admissible modifications in place; return the reactions knocked out.
    Uptake can only be opened or closed on declared external exchanges."""
    base = manifest.get("baseline", {})
    external = validate_boundary(model, manifest) if external is None else external
    killed: set[str] = set()
    knocked_genes: set[str] = set()
    # Resolve every explicit intervention first. A misspelled gene must not be
    # silently interpreted as a harmless deletion, and labels must have the
    # same GPR effect as the corresponding SBML gene-product identifiers.
    for mod in mods:
        if mod.get("op") != "knockout":
            continue
        for key, known in (("genes", model.gene_alias), ("reactions", model.rxn_index)):
            values = mod.get(key, [])
            if not isinstance(values, list) or any(not isinstance(v, str) or not v for v in values):
                raise ManifestError(f"knockout {key} must be a list of nonempty identifiers")
            for value in values:
                if value not in known:
                    kind = "gene" if key == "genes" else "reaction"
                    raise ManifestError(f"unknown knockout {kind}: {value}")
        killed.update(mod.get("reactions", []))
        knocked_genes.update(model.gene_alias[g] for g in mod.get("genes", []))
    for mod in mods:
        op = mod["op"]
        if "exchange" in mod and mod["exchange"] not in external:
            raise ManifestError(f"{mod['exchange']} is not a declared external exchange")
        if op in ("carbon_swap", "nitrogen_swap"):
            key = "carbon_exchanges" if op == "carbon_swap" else "nitrogen_exchanges"
            for rid in base.get(key, []):
                close_uptake(model, lb, ub, rid)
            open_uptake(model, lb, ub, mod["exchange"], cfg["uptake_rate"])
        elif op == "oxygen_removal":
            close_uptake(model, lb, ub, base["oxygen_exchange"])
        elif op == "close":
            close_uptake(model, lb, ub, mod["exchange"])
        elif op == "open":
            open_uptake(model, lb, ub, mod["exchange"], mod.get("rate", cfg["uptake_rate"]))
        elif op == "knockout":
            pass  # validated and resolved above, then applied as one intervention
        else:
            raise ManifestError(f"unknown modification: {op}")
    # Separate knockout records describe one intervention. Evaluate GPR OR/AND
    # logic against their union, not against each gene deletion independently.
    if knocked_genes:
        killed |= model.blocked_by_genes(knocked_genes)
    for rid in killed:
        col = model.rxn_index[rid]
        lb[col] = ub[col] = 0.0
    return sorted(killed)


# --------------------------------------------------------------------------- menu


def _as_list(v: Any) -> list[str]:
    if v is None:
        return []
    return [v] if isinstance(v, str) else list(v)


def hypothesis_targets(model: Model, h: dict[str, Any]) -> tuple[list[str], list[str]]:
    """(reactions to perturb, model genes used) of one hypothesis.

    ``perturbation: "reaction"`` means the hypothesis names exactly the reactions it lists: a gene that is
    also named (even one present in the GPR) is an annotation and is NOT deleted, because deleting it would
    remove every other reaction that gene controls.  Any other value keeps the gene-or-reaction behaviour.
    """
    reaction_level = h.get("perturbation") == "reaction"
    genes = [] if reaction_level else [model.gene_alias[g] for g in _as_list(h.get("gene")) + _as_list(h.get("genes"))
                                       if g in model.gene_alias]
    rxns = [r for r in _as_list(h.get("reactions")) if r in model.rxn_index]
    return sorted(set(rxns) | model.blocked_by_genes(set(genes))), genes


def build_menu(model: Model, manifest: dict[str, Any], max_focus: int = DEFAULT_CONFIG["max_focus_reactions"],
               external: set[str] | None = None) -> tuple[list[dict[str, Any]], list[dict[str, str]]]:
    """Derive the admissible experiment menu from context records. Returns (menu, rejections).

    A hypothesis may name candidate genes, model reactions, or both.  Reactions given directly
    are used as-is; genes are mapped through the model GPR when present.  A candidate gene that
    is absent from the model GPR (e.g. masked target assignments) is recorded as unmapped and
    does not remove a reaction-level hypothesis from the menu.
    """
    external = validate_boundary(model, manifest) if external is None else external
    ctx = manifest.get("context", {})
    evidence = ctx.get("evidence", [])
    hyps = {h["id"]: h for h in ctx.get("hypotheses", [])}
    base = manifest.get("baseline", {})
    menu: dict[str, dict[str, Any]] = {}
    rejected: list[dict[str, str]] = []

    ev_by_hyp: dict[str, list[dict[str, Any]]] = {h: [] for h in hyps}
    for ev in evidence:
        hid = ev.get("hypothesis_id")
        if hid in ev_by_hyp:
            ev_by_hyp[hid].append(ev)

    def hyp_reactions(h: dict[str, Any]) -> tuple[list[str], list[str]]:
        return hypothesis_targets(model, h)

#!/usr/bin/env python3
"""Retain every Table 1 cell from Thanapipatsiri et al. 2015, without model labels."""
import argparse
from decimal import Decimal
import hashlib
import json
from pathlib import Path
import re
import xml.etree.ElementTree as ET


def prepare(path):
    raw = path.read_bytes()
    root = ET.fromstring(raw)
    ids = {x.attrib.get('pub-id-type'): x.text for x in root.findall('.//article-meta/article-id')}
    if ids.get('doi') != '10.1186/s12934-015-0335-0' or ids.get('pmid') != '26376792':
        raise ValueError('unexpected primary article')
    table = root.find(".//table-wrap[@id='Tab1']")
    rows = [[''.join(c.itertext()).strip() for c in row] for row in table.findall('.//tr')]
    if rows[1] != ['Germicidin A', 'Germicidin B7', 'Total germicidins', 'Flaviolin'] or len(rows) != 8:
        raise ValueError('unexpected table columns or population')
    records = []
    for i, row in enumerate(rows[2:]):
        if len(row) != 5:
            raise ValueError('unexpected row width')
        for product, value in zip(rows[1], row[1:]):
            record = {'strain': row[0], 'product': product, 'raw_value': value,
                      'source_table': 'Tab1', 'source_data_row': i + 1,
                      'units': '(mAU × 10^3)/mg dry weight', 'replicates_reported': 2}
            if value == 'ND':
                record.update(status='not_determined', value=None, reported_uncertainty=None)
            elif value == 'None':
                record.update(status='not_detected', value=None, reported_uncertainty=None,
                              detection_limit=None)
            else:
                match = re.fullmatch(r'([0-9.]+)\s*±\s*([0-9.]+)', value)
                if not match:
                    raise ValueError('unexpected measured value: ' + value)
                mean, uncertainty = (Decimal(v) for v in match.groups())
                if not mean.is_finite() or not uncertainty.is_finite() or mean <= 0 or uncertainty < 0:
                    raise ValueError('invalid measured value')
                record.update(status='detected', value=float(mean), reported_uncertainty=float(uncertainty),
                              uncertainty_definition='not inferred; preserve reported ± value')
            records.append(record)
    if len({(r['strain'], r['product']) for r in records}) != 24:
        raise ValueError('duplicated or missing table cells')
    genotype_table = root.find(".//table-wrap[@id='Tab2']")
    genotypes = []
    for row in genotype_table.findall('.//tr'):
        cells = [''.join(c.itertext()).strip() for c in row]
        if cells and any(s in cells[0] for s in ('M1152', 'M1314', 'M1316', 'M1317')):
            genotypes.append({'strain': cells[0], 'description': cells[1], 'source': cells[2]})
    return {'schema': 'gspa.germicidin_primary_observations/1', 'doi': ids['doi'],
            'source_sha256': hashlib.sha256(raw).hexdigest(), 'records': records, 'genotypes': genotypes,
            'culture': {'medium': 'GYM (glucose-yeast extract-malt extract)', 'duration_days': 5,
                        'temperature_celsius': 30, 'shaking_rpm': 250, 'culture_ml': 50, 'flask_ml': 250,
                        'matrix': 'culture supernatant'},
            'interpretation': 'Production observations, not enzyme negatives or steady-state fluxes. '
                'GYM composition, secretion transport and congener mappings are not represented by the model diagnostic.'}


if __name__ == '__main__':
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--article', type=Path, required=True)
    p.add_argument('--out', type=Path, required=True)
    args = p.parse_args()
    args.out.write_text(json.dumps(prepare(args.article), indent=2, ensure_ascii=False) + '\n')
